sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartRclLinha2 = null;

    $scope.anoSelecionado2 = "";
    $scope.exibirGraficoRcl2 = false;

    function carregarDadosRcl2() {
        var filtros = {
            ano: $scope.anoSelecionado2 || ""
        };

        $scope.server.get(filtros).then(function(response) {
            var dados = response.data.dadosGraficoRCL || [];

            $timeout(function() {
                montarGraficoRcl2(dados);
            }, 300);
        });
    }

    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionado2 = ano;
        carregarDadosRcl2();
    });

    carregarDadosRcl2();

    function montarGraficoRcl2(listaDados) {
        if (!listaDados || listaDados.length === 0) {
            if (chartRclLinha2) {
                chartRclLinha2.destroy();
                chartRclLinha2 = null;
            }
            $scope.exibirGraficoRcl2 = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoRcl2 = true;
        $scope.$applyAsync();

        listaDados.sort(function(a, b) {
            return a.ano - b.ano;
        });

        var anos = [];
        var valoresNormais = [];
        var valoresAjustados = [];
        var valoresSerie = [];

        for (var i = 0; i < listaDados.length; i++) {
            anos.push(listaDados[i].ano);
            valoresNormais.push(listaDados[i].somaRclNormal / 1);
            valoresAjustados.push(listaDados[i].somaRclAjustada / 1);
            valoresSerie.push(listaDados[i].serie / 1);
        }

        var ctx = document.getElementById('graficoRclLinha2').getContext('2d');

        if (chartRclLinha2) {
            chartRclLinha2.destroy();
        }

        chartRclLinha2 = new Chart(ctx, {
            type: 'line',
            data: {
                labels: anos,
                datasets: [
                    {
                        label: 'RCL Normal',
                        data: valoresNormais,
                        borderColor: '#a7b9e8',
                        backgroundColor: '#a7b9e8',
                        fill: false,
                        tension: 0.3,
                        pointRadius: 5,
                        pointHoverRadius: 7
                    },
                    {
                        label: 'RCL Ajustada',
                        data: valoresAjustados,
                        borderColor: '#4b77bf',
                        backgroundColor: '#4b77bf',
                        fill: false,
                        tension: 0.3,
                        pointRadius: 5,
                        pointHoverRadius: 7
                    },
                    {
                        label: 'Deduções',
                        data: valoresSerie,
                        borderColor: '#D90C0C',
                        backgroundColor: '#D90C0C',
                        fill: false,
                        tension: 0.3,
                        pointRadius: 5,
                        pointHoverRadius: 7
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: { display: true, text: 'Ano' },
                        offset: true
                    },
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: 'Valor (em R$)' },
                        ticks: {
                            callback: function(value) {
                                return 'R$ ' + value.toLocaleString('pt-BR');
                            }
                        }
                    }
                },
                plugins: {
                    legend: { position: 'top' },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': R$ ' + context.parsed.y.toLocaleString('pt-BR');
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div {
 font-family: 'Roboto Flex', sans-serif;
}

.titleEnd{
   font-family: Roboto;
  font-weight: 500;
  font-style: Medium;
  font-size: 24px;
  leading-trim: NONE;
  line-height: 100%;
  letter-spacing: 0%;
	color:#021770;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};

    var anoFiltro = input.ano || "";

    var grRCL = new GlideAggregate('x_sded9_portal_t_0_u_rcl_deducoes');

    /*if (anoFiltro !== "") {
        var anoSelecionado = parseInt(anoFiltro, 10);

        // Buscar anos disponíveis
        var anosDisponiveis = [];
        var grAnos = new GlideRecord('x_sded9_portal_t_0_u_rcl_deducoes');
        grAnos.orderByDesc('u_ano');
        grAnos.query();
        while (grAnos.next()) {
            var anoAtual = parseInt(grAnos.getValue('u_ano'), 10);
            if (anosDisponiveis.indexOf(anoAtual) === -1) {
                anosDisponiveis.push(anoAtual);
            }
        }
        anosDisponiveis.sort();

        var anoAnterior = null;
        var indexAnoSelecionado = anosDisponiveis.indexOf(anoSelecionado);
        if (indexAnoSelecionado > 0) {
            anoAnterior = anosDisponiveis[indexAnoSelecionado - 1];
        }

        // Construir query para ano selecionado e ano anterior (se existir)
        if (anoAnterior !== null) {
            var qc = grRCL.addQuery('u_ano', anoSelecionado);
            qc.addOrCondition('u_ano', anoAnterior);
        } else {
            grRCL.addQuery('u_ano', anoSelecionado);
        }
    }*/

    grRCL.addAggregate('SUM', 'u_rcl_normal');
    grRCL.addAggregate('SUM', 'u_rcl_ajustada');
    grRCL.addAggregate('SUM', 'u_deducoes');
    grRCL.groupBy('u_ano');
    grRCL.orderBy('u_ano');
    grRCL.query();

    var listaRCL = [];

    while (grRCL.next()) {
        listaRCL.push({
            ano: parseInt(grRCL.getValue('u_ano'), 10),
            somaRclNormal: parseFloat(grRCL.getAggregate('SUM', 'u_rcl_normal')) || 0,
            somaRclAjustada: parseFloat(grRCL.getAggregate('SUM', 'u_rcl_ajustada')) || 0,
            serie: parseFloat(grRCL.getAggregate('SUM', 'u_deducoes')) || 0
        });
    }

    data.dadosGraficoRCL = listaRCL;
})();
